using System;using System.IO;using System.Collections.Generic;
static class LaunchOptions {
 static Dictionary<string,object> Child(Dictionary<string,object> d,string key){foreach(var p in d)if(p.Key.Equals(key,StringComparison.OrdinalIgnoreCase))return p.Value as Dictionary<string,object>;return null;}
 static string Value(Dictionary<string,object> d,string key){object v;return d!=null&&d.TryGetValue(key,out v)?v as string:null;}
 public static string SteamArguments(string steam,string appid){string users=Core.Inside(steam,"config/loginusers.vdf");if(!File.Exists(users))return null;var root=Child(Core.Vdf(File.ReadAllText(users)),"users");if(root==null)return null;string selected=null;foreach(var p in root){var d=p.Value as Dictionary<string,object>;if(Value(d,"MostRecent")=="1"){if(selected!=null)return null;selected=p.Key;}}ulong id;if(!ulong.TryParse(selected,out id))return null;string config=Core.Inside(steam,"userdata/"+((uint)(id&0xffffffff)).ToString()+"/config/localconfig.vdf");if(!File.Exists(config))return null;var node=Core.Vdf(File.ReadAllText(config));foreach(var key in new[]{"UserLocalConfigStore","Software","Valve","Steam","apps",appid}){node=Child(node,key);if(node==null)return null;}return Value(node,"LaunchOptions");}
 public static void Validate(string args){if(args==null)args="";if(args.Length>1500||args.Contains("\r")||args.Contains("\n")||args.Contains("\0"))throw new Exception("Launch arguments are too long or contain a line break");if(args.IndexOf("%command%",StringComparison.OrdinalIgnoreCase)>=0)throw new Exception("%command% wrappers are not supported by injection launch; enter only game arguments");}
}
